/**
 * Test: ForEach with multiple different tables
 *
 * This flow tests metadata extraction from various ServiceNow tables.
 * Expected label cache metadata for each forEach:
 * - change_request forEach: reference="change_request"
 * - task forEach: reference="task"
 * - alm_asset forEach: reference="alm_asset"
 */

import '@servicenow/sdk/global'
import { Flow, wfa, action, trigger } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['foreach_metadata_multiple_tables_flow'],
        name: 'ForEach Metadata - Multiple Tables Test',
        description: 'Tests metadata extraction from multiple different table types',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['scheduled_trigger'] },
        {
            table: 'change_request',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        const changes = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_changes'],
                annotation: 'Lookup change requests',
            },
            {
                table: 'change_request',
                conditions: 'state=1^active=true',
                max_results: 5,
            }
        )

        // Should extract: reference="change_request"
        wfa.flowLogic.forEach(
            wfa.dataPill(changes.Records, 'records'),
            {
                $id: Now.ID['foreach_changes'],
                annotation: 'Process each change request',
            },
            (change) => {
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['log_change'] },
                    {
                        log_level: 'info',
                        log_message: `Change: ${wfa.dataPill(change.number, 'string')}`,
                    }
                )
            }
        )

        // Test 2: task table
        const tasks = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_tasks'],
                annotation: 'Lookup tasks',
            },
            {
                table: 'task',
                conditions: 'active=true^priority=1',
                max_results: 10,
            }
        )

        // Should extract: reference="task"
        wfa.flowLogic.forEach(
            wfa.dataPill(tasks.Records, 'records'),
            {
                $id: Now.ID['foreach_tasks'],
                annotation: 'Process each task',
            },
            (task) => {
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['log_task'] },
                    {
                        log_level: 'info',
                        log_message: `Task: ${wfa.dataPill(task.short_description, 'string')}`,
                    }
                )
            }
        )

        // Test 3: alm_asset table
        const assets = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_assets'],
                annotation: 'Lookup assets',
            },
            {
                table: 'alm_hardware',
                conditions: 'active=true',
                max_results: 10,
            }
        )

        // Should extract: reference="alm_asset"
        wfa.flowLogic.forEach(
            wfa.dataPill(assets.Records, 'records'),
            {
                $id: Now.ID['foreach_assets'],
                annotation: 'Process each asset',
            },
            (asset) => {
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['log_asset'] },
                    {
                        log_level: 'info',
                        log_message: `Asset: ${wfa.dataPill(asset.comments, 'string')}`,
                    }
                )
            }
        )
    }
)
